import React, { useState, useRef, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { sendPhoneOtp } from '../services/api';
import { X, User, ShieldCheck, ArrowRight, AlertCircle } from 'lucide-react';
import Logo from './Logo';
import styles from './LoginModal.module.css';

export default function LoginModal() {
  const { loginModalOpen, closeLoginModal, loginWithPhone } = useAuth();

  const [step, setStep] = useState(1); // 1: Name & Phone, 2: OTP
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [devOtp, setDevOtp] = useState('');
  const [resendTimer, setResendTimer] = useState(30);

  const otpInputsRef = useRef([]);

  // Reset state whenever modal opens
  useEffect(() => {
    if (loginModalOpen) {
      setStep(1);
      setError('');
      setLoading(false);
      setOtp(['', '', '', '', '', '']);
      setDevOtp('');
      setResendTimer(30);
    }
  }, [loginModalOpen]);

  // Resend countdown timer
  useEffect(() => {
    if (step === 2 && resendTimer > 0) {
      const timer = setInterval(() => {
        setResendTimer((t) => t - 1);
      }, 1000);
      return () => clearInterval(timer);
    }
  }, [step, resendTimer]);

  // Focus first OTP input when step 2 opens
  useEffect(() => {
    if (step === 2) {
      setTimeout(() => {
        otpInputsRef.current[0]?.focus();
      }, 100);
    }
  }, [step]);

  if (!loginModalOpen) return null;

  // Clean 10-digit phone
  const cleanPhone = phone.replace(/[^0-9]/g, '').slice(-10);

  // Handle Step 1: Send OTP
  const handleSendOtp = async (e) => {
    e?.preventDefault();
    setError('');

    if (!name.trim()) {
      setError('Please enter your full name');
      return;
    }
    if (cleanPhone.length !== 10) {
      setError('Please enter a valid 10-digit mobile number');
      return;
    }

    setLoading(true);
    try {
      const res = await sendPhoneOtp({ phone: cleanPhone });
      if (res.data?.devOtp) {
        setDevOtp(res.data.devOtp);
      }
      setStep(2);
      setResendTimer(30);
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to send OTP. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // Handle Step 2: Verify OTP
  const handleVerifyOtp = async (e) => {
    e?.preventDefault();
    const enteredOtp = otp.join('').trim();
    if (enteredOtp.length !== 6) {
      setError('Please enter the complete 6-digit OTP');
      return;
    }

    setError('');
    setLoading(true);
    try {
      await loginWithPhone(name.trim(), cleanPhone, enteredOtp);
      closeLoginModal();
    } catch (err) {
      setError(err.response?.data?.message || 'Invalid verification code. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // Handle individual OTP box typing
  const handleOtpChange = (index, val) => {
    const char = val.slice(-1);
    if (char && !/[0-9]/.test(char)) return;

    const newOtp = [...otp];
    newOtp[index] = char;
    setOtp(newOtp);

    // Auto advance to next box
    if (char && index < 5) {
      otpInputsRef.current[index + 1]?.focus();
    }

    // If all 6 digits entered, auto-verify
    if (char && index === 5 && newOtp.every((d) => d !== '')) {
      const fullOtp = newOtp.join('');
      setLoading(true);
      loginWithPhone(name.trim(), cleanPhone, fullOtp)
        .then(() => closeLoginModal())
        .catch((err) => {
          setError(err.response?.data?.message || 'Invalid OTP. Please try again.');
          setLoading(false);
        });
    }
  };

  const handleOtpKeyDown = (index, e) => {
    if (e.key === 'Backspace' && !otp[index] && index > 0) {
      otpInputsRef.current[index - 1]?.focus();
    }
  };

  const handleOtpPaste = (e) => {
    e.preventDefault();
    const pastedData = e.clipboardData.getData('text').replace(/[^0-9]/g, '').slice(0, 6);
    if (!pastedData) return;
    const newOtp = [...otp];
    for (let i = 0; i < pastedData.length; i++) {
      newOtp[i] = pastedData[i];
    }
    setOtp(newOtp);
    if (pastedData.length === 6) {
      setLoading(true);
      loginWithPhone(name.trim(), cleanPhone, pastedData)
        .then(() => closeLoginModal())
        .catch((err) => {
          setError(err.response?.data?.message || 'Invalid OTP. Please try again.');
          setLoading(false);
        });
    } else {
      otpInputsRef.current[pastedData.length]?.focus();
    }
  };

  return (
    <div className={styles.overlay} onClick={closeLoginModal}>
      <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
        {/* Close Button */}
        <button
          type="button"
          className={styles.closeBtn}
          onClick={closeLoginModal}
          aria-label="Close modal"
        >
          <X size={18} />
        </button>

        {/* Brand Logo */}
        <div className={styles.brandWrap}>
          <Logo size="md" showTagline={false} theme="forest" />
        </div>

        {/* Header */}
        <div className={styles.header}>
          <h2 className={styles.title}>
            {step === 1 ? 'Login to ProBridge' : 'Verify Mobile Number'}
          </h2>
          <p className={styles.subtitle}>
            {step === 1 ? (
              'Enter your name and mobile number to access your account'
            ) : (
              <>
                Enter the 6-digit code sent to{' '}
                <span className={styles.phoneHighlight}>+91 {cleanPhone}</span>
                <button
                  type="button"
                  className={styles.editPhoneBtn}
                  onClick={() => { setStep(1); setError(''); }}
                >
                  Edit
                </button>
              </>
            )}
          </p>
        </div>

        {/* Error Banner */}
        {error && (
          <div className={styles.errorBanner}>
            <AlertCircle size={16} />
            <span>{error}</span>
          </div>
        )}

        {/* Dev OTP Hint (Automatic helper if dev OTP returned) */}
        {devOtp && step === 2 && (
          <div className={styles.devOtpHint}>
            <span>Dev Verification Code:</span>
            <span
              className={styles.devOtpBadge}
              style={{ cursor: 'pointer' }}
              onClick={() => {
                const chars = devOtp.split('').slice(0, 6);
                setOtp(chars);
              }}
              title="Click to auto-fill OTP"
            >
              {devOtp} (Click to fill)
            </span>
          </div>
        )}

        {/* Step 1: Name & Mobile Number */}
        {step === 1 ? (
          <form onSubmit={handleSendOtp} className={styles.form}>
            <div className={styles.field}>
              <label className={styles.label}>Full Name</label>
              <div className={styles.inputWrap}>
                <User size={18} className={styles.fieldIcon} />
                <input
                  type="text"
                  className={styles.input}
                  placeholder="Enter your full name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  autoFocus
                  required
                />
              </div>
            </div>

            <div className={styles.field}>
              <label className={styles.label}>Mobile Number</label>
              <div className={styles.phoneInputWrap}>
                <div className={styles.countryCode}>
                  <span>🇮🇳</span>
                  <span>+91</span>
                </div>
                <input
                  type="tel"
                  className={styles.phoneInput}
                  placeholder="10-digit mobile number"
                  maxLength={10}
                  value={phone}
                  onChange={(e) => setPhone(e.target.value.replace(/[^0-9]/g, ''))}
                  required
                />
              </div>
            </div>

            <button
              type="submit"
              className={styles.submitBtn}
              disabled={loading || !name.trim() || cleanPhone.length !== 10}
            >
              {loading ? (
                'Sending OTP…'
              ) : (
                <>
                  <span>Continue</span>
                  <ArrowRight size={17} />
                </>
              )}
            </button>
          </form>
        ) : (
          /* Step 2: OTP Verification */
          <form onSubmit={handleVerifyOtp} className={styles.form}>
            <div className={styles.otpInputWrap} onPaste={handleOtpPaste}>
              {otp.map((digit, idx) => (
                <input
                  key={idx}
                  ref={(el) => (otpInputsRef.current[idx] = el)}
                  type="text"
                  inputMode="numeric"
                  maxLength={1}
                  className={`${styles.otpDigit} ${digit ? styles.otpDigitFilled : ''}`}
                  value={digit}
                  onChange={(e) => handleOtpChange(idx, e.target.value)}
                  onKeyDown={(e) => handleOtpKeyDown(idx, e)}
                />
              ))}
            </div>

            <button
              type="submit"
              className={styles.submitBtn}
              disabled={loading || otp.some((d) => d === '')}
            >
              {loading ? (
                'Verifying…'
              ) : (
                <>
                  <ShieldCheck size={18} />
                  <span>Verify &amp; Login</span>
                </>
              )}
            </button>

            <div className={styles.resendRow}>
              {resendTimer > 0 ? (
                <span>Resend OTP in <span className={styles.resendTimer}>{resendTimer}s</span></span>
              ) : (
                <button
                  type="button"
                  className={styles.resendBtn}
                  onClick={handleSendOtp}
                  disabled={loading}
                >
                  Resend OTP
                </button>
              )}
            </div>
          </form>
        )}

        <p className={styles.termsText}>
          By continuing, you agree to ProBridge's Terms of Service and Privacy Policy. Zero Spam Guarantee.
        </p>
      </div>
    </div>
  );
}
